import{_ as t,C as r,o as n,c,a5 as a,j as i,E as o}from"./chunks/framework.a5no_H3L.js";const g=JSON.parse('{"title":"场景、坐标系与 Transform","description":"你已经在 Inspector 里改过 Position，但可能没想清楚\\"这个数值相对于谁\\"。读完这一篇，你能说清 Unity 的坐标系、世界坐标与本地坐标的区别，以及父子关系如何改变一个物体的坐标。","frontmatter":{"type":"explanation","level":"basic"},"headers":[],"relativePath":"unity/03-scene-core/chapter-01-scene-transform.md","filePath":"unity/03-scene-core/chapter-01-scene-transform.md"}'),d={name:"unity/03-scene-core/chapter-01-scene-transform.md"},l={"data-src-line":"12","data-src-file":"unity/03-scene-core/chapter-01-scene-transform.md"};function h(p,e,m,f,u,k){const s=r("SvgDiagram");return n(),c("div",null,[e[0]||(e[0]=a('<h1 id="场景、坐标系与-transform" tabindex="-1" data-src-line="2" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">场景、坐标系与 Transform <a class="header-anchor" href="#场景、坐标系与-transform" aria-label="Permalink to &quot;场景、坐标系与 Transform&quot;">​</a></h1><p data-src-line="4" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">你已经在 Inspector 里改过 Position，但可能没想清楚&quot;这个数值相对于谁&quot;。读完这一篇，你能说清 Unity 的坐标系、世界坐标与本地坐标的区别，以及父子关系如何改变一个物体的坐标。</p><h2 id="_1-场景是坐标系的载体" tabindex="-1" data-src-line="6" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">1. 场景是坐标系的载体 <a class="header-anchor" href="#_1-场景是坐标系的载体" aria-label="Permalink to &quot;1. 场景是坐标系的载体&quot;">​</a></h2><p data-src-line="8" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">场景（Scene）是游戏世界的一个容器，每个场景有自己的三维空间。场景里的每个物体都有一个位置，这个位置用坐标描述。</p><p data-src-line="10" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">Unity 使用<strong>左手坐标系</strong>：</p>',5)),i("p",l,[o(s,{src:"/unity/03-scene-core-chapter-01-left-handed-coordinate.svg",alt:"Unity 左手坐标系：X 轴向右、Y 轴向上、Z 轴向前（屏幕里）"})]),e[1]||(e[1]=a(`<p data-src-line="14" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">判断左右手系有个简单方法：伸出左手，拇指、食指、中指两两垂直，让拇指指向 X（右）、食指指向 Y（上），中指自然指向的就是 Z（前）。Unity 就是这样。Unreal 也是左手系，而一些建模软件（如 3ds Max 用右手系，Blender 是 Z 轴向上），导入模型时可能需要调整，这是后话。</p><p data-src-line="16" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">单位是<strong>米</strong>。Unity 的物理引擎默认按 1 单位 = 1 米计算，所以一个&quot;高 2&quot;的立方体在物理世界里是 2 米高。这也是为什么之前提到：如果物体尺寸和真实世界差太多，物理表现会怪异。</p><h2 id="_2-transform-的三个分量" tabindex="-1" data-src-line="18" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">2. Transform 的三个分量 <a class="header-anchor" href="#_2-transform-的三个分量" aria-label="Permalink to &quot;2. Transform 的三个分量&quot;">​</a></h2><p data-src-line="20" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">每个物体都有一个 <code>Transform</code> 组件，描述它的空间状态，由三部分组成：</p><table tabindex="0"><thead data-src-line="22" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md"><tr data-src-line="22" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md"><th>分量</th><th>含义</th></tr></thead><tbody data-src-line="24" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md"><tr data-src-line="24" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md"><td>Position（位置）</td><td>物体在世界（或父物体）空间中的位置，<code>Vector3</code></td></tr><tr data-src-line="25" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md"><td>Rotation（旋转）</td><td>物体的朝向，用四元数 <code>Quaternion</code> 存储，Inspector 里显示为欧拉角</td></tr><tr data-src-line="26" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md"><td>Scale（缩放）</td><td>物体沿各轴的缩放倍数，<code>Vector3</code></td></tr></tbody></table><p data-src-line="28" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">Inspector 里看到的 Position、Rotation、Scale 就是这三者的可读形式。脚本里 <code>transform.position</code>、<code>transform.rotation</code>、<code>transform.localScale</code> 对应它们。</p><h2 id="_3-世界坐标与本地坐标" tabindex="-1" data-src-line="30" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">3. 世界坐标与本地坐标 <a class="header-anchor" href="#_3-世界坐标与本地坐标" aria-label="Permalink to &quot;3. 世界坐标与本地坐标&quot;">​</a></h2><p data-src-line="32" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">这是最容易混淆的点。一个物体的坐标有两种读法：</p><ul data-src-line="34" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md"><li data-src-line="34" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md"><strong>世界坐标</strong>：物体在整个场景里的绝对位置。脚本里是 <code>transform.position</code>。</li><li data-src-line="35" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md"><strong>本地坐标</strong>：物体相对于<strong>父物体</strong>的位置。脚本里是 <code>transform.localPosition</code>。</li></ul><p data-src-line="37" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">对没有父物体的物体，两者相同。但一旦物体有了父物体，它们就分开了。</p><p data-src-line="39" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">举个例子：父物体 A 在世界坐标 (10, 0, 0)，子物体 B 的本地坐标是 (1, 0, 0)。那么 B 的世界坐标是 (11, 0, 0)——本地坐标是&quot;相对父物体的偏移&quot;，世界坐标是&quot;绝对位置&quot;。</p><p data-src-line="41" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">移动父物体 A，子物体 B 会跟着动（B 的世界坐标变，但本地坐标 (1,0,0) 不变）。这就是父子关系的核心作用：<strong>用父物体组织一组物体，移动父物体就移动整组</strong>。</p><h2 id="_4-父子关系" tabindex="-1" data-src-line="43" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">4. 父子关系 <a class="header-anchor" href="#_4-父子关系" aria-label="Permalink to &quot;4. 父子关系&quot;">​</a></h2><p data-src-line="45" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">在 Hierarchy 里，把一个物体拖到另一个物体下面，就建立了父子关系。子物体继承父物体的位置、旋转和缩放：</p><ul data-src-line="47" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md"><li data-src-line="47" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">旋转父物体，子物体跟着转。</li><li data-src-line="48" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">缩放父物体，子物体跟着缩放（子物体的世界缩放 = 父子缩放相乘）。</li><li data-src-line="49" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">删除父物体，子物体一并删除。</li></ul><p data-src-line="51" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">用途很多：一辆车是父物体，四个轮子是子物体，移动车就带动轮子；一个角色是父物体，武器是子物体，角色转身武器也跟着转。</p><p data-src-line="53" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">脚本里操作父子关系：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transform.parent </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> otherTransform;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 设置父物体</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transform.parent </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 解除父子关系</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transform.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetParent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(other, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 第二个参数控制是否保留世界坐标</span></span></code></pre></div><p data-src-line="61" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md"><code>SetParent</code> 的第二个参数值得注意：<code>true</code> 保留子物体的世界坐标（改变本地坐标来补偿），<code>false</code> 保留本地坐标。默认行为有时不符合直觉，明确传参可以避免物体&quot;跳&quot;到奇怪的位置。</p><h2 id="_5-旋转为什么用四元数" tabindex="-1" data-src-line="63" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">5. 旋转为什么用四元数 <a class="header-anchor" href="#_5-旋转为什么用四元数" aria-label="Permalink to &quot;5. 旋转为什么用四元数&quot;">​</a></h2><p data-src-line="65" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">Inspector 里旋转显示为三个欧拉角（绕 X/Y/Z 各转多少度），但脚本里 <code>rotation</code> 是四元数（<code>Quaternion</code>）。原因是欧拉角存在<strong>万向锁</strong>问题：某些角度组合下，旋转会丢失一个自由度，导致旋转表现异常。</p><p data-src-line="67" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">四元数用四个数表示旋转，避免了万向锁，插值也更平滑。代价是四元数不直观。</p><p data-src-line="69" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">对初学者，记住两条：</p><ul data-src-line="71" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md"><li data-src-line="71" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">不要手动改四元数的四个分量，那没有直观意义。</li><li data-src-line="72" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">需要&quot;转多少度&quot;时，用 <code>Quaternion.Euler(x, y, z)</code> 从欧拉角构造，或用 <code>transform.Rotate</code> 相对旋转。</li></ul><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transform.rotation </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Quaternion.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Euler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">45</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 绕 Y 轴转 45 度</span></span></code></pre></div><h2 id="_6-动手验证" tabindex="-1" data-src-line="78" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">6. 动手验证 <a class="header-anchor" href="#_6-动手验证" aria-label="Permalink to &quot;6. 动手验证&quot;">​</a></h2><ol data-src-line="80" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md"><li data-src-line="80" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">场景里建两个 Cube，名字分别叫 <code>Parent</code> 和 <code>Child</code>。</li><li data-src-line="81" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">把 <code>Child</code> 拖到 <code>Parent</code> 下面，成为其子物体。</li><li data-src-line="82" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">选中 <code>Parent</code>，看它和 <code>Child</code> 的 Inspector：<code>Parent</code> 的 Position 是 (0,0,0)，<code>Child</code> 的 Position 显示的是<strong>本地坐标</strong>。</li><li data-src-line="83" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">移动 <code>Parent</code>，观察 <code>Child</code> 跟着动，但 <code>Child</code> 的本地坐标不变。</li><li data-src-line="84" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">在脚本里打印对比 <code>transform.position</code> 和 <code>transform.localPosition</code>，确认两者对子物体的差异。</li></ol><p data-src-line="86" data-src-file="unity/03-scene-core/chapter-01-scene-transform.md">下一步深入组件的通信方式：<a href="./chapter-02-components-messages.html">组件与消息</a>。</p>`,28))])}const E=t(d,[["render",h]]);export{g as __pageData,E as default};
